// Writes apps/web/tsconfig.v1.paths.json from apps/web/src/v1/aliases.json (generated by scripts/v1-lift.py), so tsc
// resolves the lifted v1 tree's package specifiers (@goat/...) and "~/" the way vite does (vite.config.ts reads the
// same aliases.json). Run before typechecking the v1 tree: node apps/web/scripts/v1-paths.mjs
import { readFileSync, writeFileSync } from "node:fs";
import { dirname, join, relative } from "node:path";
import { fileURLToPath } from "node:url";

const web = join(dirname(fileURLToPath(import.meta.url)), "..");
const repo = join(web, "../..");
const aliases = JSON.parse(readFileSync(join(web, "src/v1/aliases.json"), "utf8"));
// Hand-written seam answers for npm modules (e.g. @tanstack/react-router), next to the generated map.
const npmAliases = JSON.parse(readFileSync(join(web, "src/v1/seam/npm-aliases.json"), "utf8"));
delete npmAliases["//"];
Object.assign(aliases, npmAliases);
const paths = {};
for (const [spec, target] of Object.entries(aliases)) {
  const rel = "./" + relative(web, join(repo, target));
  if (spec === "~") paths["~/*"] = [rel + "/*"];
  else paths[spec] = [rel];
}
writeFileSync(
  join(web, "tsconfig.v1.paths.json"),
  JSON.stringify({ "//": "generated by apps/web/scripts/v1-paths.mjs from src/v1/aliases.json", compilerOptions: { paths } }, null, 2) + "\n",
);
